from typing import Dict, List
from time import sleep

from taf.rfrl.procedures.cloud.setups_teardowns.testing_env import TestingEnv
from taf.rfrl.procedures.resources.python.bts.components.du.du import Du
from taf.rfrl.procedures.resources.python.bts.components.rmod.cloud_rmod import CloudRmod
from taf.rfrl.procedures.resources.python.bts.utils.exceptions import ResultError
from taf.rfrl.procedures.resources.python.bts.utils.measurements import is_measurement_numeric
from taf.rfrl.procedures.resources.python.bts.utils.pretty_logger import log_info, log_debug, pretty_log
from taf.rfrl.procedures.resources.python.bts.utils.timer import is_in_utc_format


def general_siso_auto_cloud_rf_statistics_diagnostic_test(testing_env: TestingEnv, rmod_name: str):
    """
    Based on:
    QC Test ID: 36490
    QC Test Name: [1.0] CB006992_40_OAM_TDD_SA_Initiate_RF_Statistics_diagnostic_test_and_Deletion_Statistics_Test_Results_via_NMS_DC1

    Should report to:
    QC Test ID: 36490
    QC Test Name: [1.0] CB006992_40_OAM_TDD_SA_Initiate_RF_Statistics_diagnostic_test_and_Deletion_Statistics_Test_Results_via_NMS_DC1

    :param testing_env: testing environment prepared for this test case
    :param rmod_name: name of rmod for which RF Statistics Diagnostic Test should be run;
                      can be taken from "RMOD ID" field of RMOD details in DU WebEM;
                      i.e. 'RMOD-1'
    """
    bts = testing_env.btss[0]
    errors = testing_env.errors

    bts.rmods.check_if_name_exists(name=rmod_name)

    for du in bts.dus:
        try:
            _start_rf_statistics_diagnostic_test_for_selected_rmod(du, rmod_name)
            _validate_rf_statistics_diagnostic_test_results_for_selected_rmod(du, rmod_name)
            _clear_rf_statistics_diagnostic_test_results(du)
            sleep(30)
            _start_rf_statistics_diagnostic_test_for_all_rmods(du)
            _validate_rf_statistics_diagnostic_test_results_for_all_rmods(du)
            _clear_rf_statistics_diagnostic_test_results(du)
        except ResultError as exc:
            errors.add_from_exception(exc)

    errors.check()


def teardown_for_general_siso_auto_rf_statistics_diagnostic_test(testing_env: TestingEnv):
    """
    Teardown for general_siso_auto_cloud_rf_statistics_diagnostic_test TC,
    must be used in [Teardown] of Robot Framework test suite.
    :param testing_env: testing environment prepared for this test case
    """
    bts = testing_env.btss[0]

    for du in bts.dus:
        sleep(30)
        _clear_rf_statistics_diagnostic_test_results(du)
        du.check_state(state='on_air')


def _start_rf_statistics_diagnostic_test_for_selected_rmod(du: Du, rmod_name: str):
    rmod = du.rmods.find_by_name(name=rmod_name,
                                 raise_exc=True)

    du.rf_diagnostic_test.run_rf_statistics_diagnostic_test(rmod=rmod)


def _start_rf_statistics_diagnostic_test_for_all_rmods(du: Du):
    du.rf_diagnostic_test.run_rf_statistics_diagnostic_test(rmod=None)


def _clear_rf_statistics_diagnostic_test_results(du: Du):
    du.rf_diagnostic_test.clear_rf_statistics_diagnostic_test_results()


@pretty_log
def _validate_rf_statistics_diagnostic_test_results_for_selected_rmod(du: Du, rmod_name: str):
    rmod = du.rmods.find_by_name(name=rmod_name)
    test_results_from_api = du.rf_diagnostic_test.get_rf_statistics_diagnostic_test_results()

    dist_name = f'MRBTS-{{}}/MNL-1/MNLENT-1/TEST-1/RFSTATREQ-0/RFSTATRES-{rmod.id}'
    test_results_from_config = du.config.get_many(dist_names=[dist_name])
    _validate_rf_statistics_diagnostic_test_results(api_results=test_results_from_api,
                                                    config_results=test_results_from_config,
                                                    rmods=[rmod])


@pretty_log
def _validate_rf_statistics_diagnostic_test_results_for_all_rmods(du: Du):
    rmods = du.rmods
    test_results_from_api = du.rf_diagnostic_test.get_rf_statistics_diagnostic_test_results()
    test_results_from_config = {}

    for rmod in rmods:
        dist_name = du.config.format_dist_name(f'MRBTS-{{}}/MNL-1/MNLENT-1/TEST-1/RFSTATREQ-0/RFSTATRES-{rmod.id}')
        test_results_from_config[dist_name] = du.config.get_many(dist_names=[dist_name])[dist_name]

    _validate_rf_statistics_diagnostic_test_results(api_results=test_results_from_api,
                                                    config_results=test_results_from_config,
                                                    rmods=rmods)


@pretty_log
def _validate_rf_statistics_diagnostic_test_results(api_results: Dict, config_results: Dict, rmods: List[CloudRmod]):
    errors = []

    for rmod in rmods:
        log_info(f'Validating RF Statistics Diagnostic test results for {rmod.name}', to_console=True)

        source = 'API response'
        api_result_for_rmod = _get_api_result_for_rmod(results=api_results,
                                                       rmod=rmod,
                                                       errors=errors)
        if api_result_for_rmod:

            _validate_start_time(start_time=api_result_for_rmod['actual_start_time'],
                                 rmod=rmod,
                                 errors=errors,
                                 source=source)
            _validate_stop_time(stop_time=api_result_for_rmod['actual_stop_time'],
                                rmod=rmod,
                                errors=errors,
                                source=source)
            _validate_test_outcome(test_outcome=api_result_for_rmod['test_outcome'],
                                   test_result=api_result_for_rmod['result'],
                                   rmod=rmod,
                                   errors=errors,
                                   source=source)
            _validate_temperature_result(
                temperature_result=api_result_for_rmod['rf_temperature_supervision'][0]['temperature_value'],
                rmod=rmod,
                errors=errors,
                source=source)
            _validate_ethernet_packet_monitoring_result(
                epm_results=api_result_for_rmod['rf_ethernet_packet_monitoring'],
                rmod=rmod,
                errors=errors,
                source=source)

        source = 'DU configuration'
        config_result_for_rmod = _get_config_result_for_rmod(results=config_results,
                                                             rmod=rmod,
                                                             errors=errors)

        if config_results:
            _validate_start_time(start_time=config_result_for_rmod['actualStartTime'],
                                 rmod=rmod,
                                 errors=errors,
                                 source=source)
            _validate_stop_time(stop_time=config_result_for_rmod['actualStopTime'],
                                rmod=rmod,
                                errors=errors,
                                source=source)
            _validate_test_outcome(test_outcome=config_result_for_rmod['testOutcome'],
                                   test_result=config_result_for_rmod['result'],
                                   rmod=rmod,
                                   errors=errors,
                                   source=source)
            _validate_temperature_result(
                temperature_result=config_result_for_rmod['rfTemperatureSupervision'][0]['temperatureValue'],
                rmod=rmod,
                errors=errors,
                source=source)
            _validate_ethernet_packet_monitoring_result(epm_results=config_result_for_rmod['ethernetPacketMonitoring'],
                                                        rmod=rmod,
                                                        errors=errors,
                                                        source=source)

        if errors:
            error_msg = 'Validation of RF Statistics Diagnostic test results failed due to following errors:'

            for error in errors:
                error_msg += f'\n{error}'

            raise ResultError(error_msg)


def _get_api_result_for_rmod(results: Dict, rmod: CloudRmod, errors: List[str]) -> Dict:
    log_debug(f'Getting test results for {rmod.name} from API response')
    result_for_rmod = None

    for result in results['rf_statistics_diagnostic_test_results']:
        if str(int(result['radio_id'])) == rmod.id:
            result_for_rmod = result['results']
            log_debug(f'Test results for {rmod.name} from API response: \n{result_for_rmod}')
            break

    if not result_for_rmod:
        errors.append(f'{rmod.name}: no test results for this RMOD in API response')

    return result_for_rmod


def _get_config_result_for_rmod(results: Dict, rmod: CloudRmod, errors: List[str]) -> Dict:
    log_debug(f'Getting test results for {rmod.name} from DU configuration')
    result_for_rmod = None

    for dist_name, result in results.items():
        if dist_name.endswith(f'RFSTATRES-{rmod.id}'):
            result_for_rmod = result
            log_debug(f'Test results for {rmod.name} from DU configuration: \n{result_for_rmod}')
            break

    if not result_for_rmod:
        errors.append(f'{rmod.name}: no test results for this RMOD in DU configuration')

    return result_for_rmod


def _validate_start_time(start_time: str, rmod: CloudRmod, errors: List[str], source: str):
    log_debug(f'Validating test start time for {rmod.name} in {source}')

    if not is_in_utc_format(date_time=start_time):
        errors.append(f'{rmod.name}: test start time {start_time} not in UTC format in {source}')


def _validate_stop_time(stop_time: str, rmod: CloudRmod, errors: List[str], source: str):
    log_debug(f'Validating test stop time for {rmod.name} in {source}')

    if not is_in_utc_format(date_time=stop_time):
        errors.append(f'{rmod.name}: test stop time {stop_time} not in UTC format in {source}')


def _validate_test_outcome(test_outcome: str, test_result: str, rmod: CloudRmod, errors: List[str], source: str):
    log_debug(f'Validating test outcome and test result for {rmod.name} in {source}')

    if test_outcome.lower() != 'pass' and test_result.lower() != 'success':
        errors.append(f'{rmod.name}: test outcome is {test_outcome} but it should be "pass" and '
                      f'test result is {test_result} but it should be "success" in {source}')


def _validate_temperature_result(temperature_result: str, rmod: CloudRmod, errors: List[str], source: str):
    log_debug(f'Validating temperature result for {rmod.name} in {source}')

    if not is_measurement_numeric(temperature_result):
        errors.append(f'{rmod.name}: {temperature_result} temperature value is not a number in {source}')


def _validate_ethernet_packet_monitoring_result(epm_results: List[Dict], rmod: CloudRmod, errors: List[str],
                                                source: str):
    log_debug(f'Validating Ethernet Packet Monitoring result for {rmod.name} in {source}')
    expected_keys = {
        'DU configuration': ['port', 'receivedErroredFrames', 'receivedFrames', 'receivedMulticastFrames',
                             'receivedOctets', 'receivedUnknownTypeFrames', 'receivedUnknownVLANFrames', 'startTime',
                             'transmittedFrames', 'transmittedMulticastFrames', 'transmittedOctets'],
        'API response': ['port', 'received_errored_frames', 'received_frames', 'received_multicast_frames',
                         'received_octets', 'received_unknown_type_frames', 'received_unknown_vlan_frames',
                         'start_time', 'transmitted_frames', 'transmitted_multicast_frames', 'transmitted_octets']}

    for epm_result in epm_results:
        for expected_key in expected_keys[source]:
            if expected_key not in epm_result:
                errors.append(
                    f'{rmod.name}: missing {expected_key} value in ethernet packet monitoring result in {source}')

            value = epm_result[expected_key]

            if 'time' in expected_key.lower():
                if not is_in_utc_format(date_time=value):
                    errors.append(f"{rmod.name}: {expected_key}'s value {value} is not in UTC format in {source}")
            elif not is_measurement_numeric(value):
                errors.append(f"{rmod.name}: {expected_key}'s value {value} is not a number in {source}")

            if rmod.link_protocol == 'ecpri' and ('transmitted' or 'received' in expected_key.lower()):
                if str(value) == '-1':
                    errors.append(f"{rmod.name}: {expected_key}'s value {value} should not be equal to -1 "
                                  f"for {rmod.rmod_link_protocol.upper()} RMODs in {source}")
